def main()->int:
    ap=argparse.ArgumentParser();ap.add_argument("--diagnostic-pointer",type=Path,default=Path(r"results/trajectory_build_off_network_diagnostic_latest_pointer.json"));ap.add_argument("--map-pointer",type=Path,default=Path(r"results/trajectory_build_map_match_production_latest_pointer.json"));ap.add_argument("--network-pointer",type=Path,default=Path(r"results/network_freeze_latest_network_pointer.json"));ap.add_argument("--quality-check-form",type=Path,default=Path(r"results/trajectory_build_manual_spatial_qa_20260717_183448\manual_quality_check_form.csv"));ap.add_argument("--trip-summary",type=Path,default=Path(r"results/trajectory_build_manual_qa_staging_20260717_183440\trip_summary.parquet"));ap.add_argument("--output-root",type=Path,default=Path(r"results/rnee_build"));args=ap.parse_args();diag=load(args.diagnostic_pointer);candidates=pd.read_csv(diag["candidates"]);quality_check=pd.read_csv(args.quality_check_form);trip_lookup=pd.read_parquet(args.trip_summary,columns=["pilot_trip_id","source_file"]);quality_check=quality_check.merge(trip_lookup,on="pilot_trip_id",how="left",validate="one_to_one");missed=quality_check[(quality_check["quality_rating"]=="incorrect")&(~quality_check["pilot_trip_id"].isin(candidates["pilot_trip_id"]))].copy();missed=missed[["source_file","VehId","Trip","pilot_trip_id","matched_coverage","edge_association_coverage","distance_p95_m","has_route_discontinuity"]];missed["raw_bbox_diagonal_m"]=pd.NA;missed["validation_category"]="known_incorrect_not_candidate";candidates["validation_category"]="abstention_candidate";selected=pd.concat([candidates,missed],ignore_index=True,sort=False);selected_ids=set(selected["pilot_trip_id"]);pointer=load(args.map_pointer);manifest=load(Path(pointer["manifest"]));point_frames=[]
