    form=out/"quality_1_off_network_validation.csv";pd.DataFrame(rows).to_csv(form,index=False,encoding="utf-8-sig");(out/"index.html").write_text("<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><title>TRAJECTORY_BUILD 非道路轨迹弃权质量确认</title><style>body{font-family:Arial;margin:20px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:18px}article{border:1px solid #ddd;padding:8px}img{width:100%}</style></head><body><h1>TRAJECTORY_BUILD 非道路/停车场轨迹弃权质量确认</h1><p>仅填写 quality_rating：abstain=应停止赋予道路语义；retain=应保留道路匹配；uncertain=无法判定。</p><main>"+"\n".join(cards)+"</main></body></html>\n",encoding="utf-8");(out/"README.md").write_text("# TRAJECTORY_BUILD off-network candidate validation\n\nQuality check all maps and fill only `quality_rating` with `abstain`, `retain`, or `uncertain`. `abstain` means the raw VED trace is mainly off-network, in an open lot/parking area, or otherwise should not inherit surrounding-road semantics. No row or trip will be deleted.\n",encoding="utf-8");summary={"experiment":"TRAJECTORY_BUILD","stage":"off_network_candidate_manual_qa","status":"REQUIRES_QUALITY_CHECK1_OFF_NETWORK_VALIDATION","created_at_utc":datetime.now(timezone.utc).isoformat(),"candidate_count":len(candidates),"known_incorrect_not_candidate_count":len(missed),"audit_count":len(rows),"quality_rating_column":"quality_rating","allowed_ratings":["abstain","retain","uncertain"],"secondary_quality_check_used":False,"production_data_modified":False,"quality_check_form":str(form),"index_html":str(out/"index.html"),"output_directory":str(out)};dump(out/"off_network_candidate_qa_summary.json",summary);dump(args.output_root/"trajectory_build_off_network_candidate_qa_latest_pointer.json",{"status":summary["status"],"summary":str(out/"off_network_candidate_qa_summary.json"),"quality_check_form":str(form),"index_html":str(out/"index.html"),"output_directory":str(out)});roads.clear();gc.collect();print(json.dumps(summary,ensure_ascii=False,indent=2));return 0
